import Foundation
import CoreMedia
import CoreVideo
import OSLog
import os

private let logger = Logger(subsystem: "com.fakeme.core", category: "SyntheticFrameProvider")

/// Deterministic, headless frame provider capable of generating procedural video patterns.
public final class SyntheticFrameProvider: VideoFrameProvider, @unchecked Sendable {
    
    /// Procedural visual patterns generated by the provider.
    public enum Pattern: Sendable {
        /// Uniform solid color (BGRA components, alpha is always 255).
        case solidColor(b: UInt8, g: UInt8, r: UInt8)
        
        /// Standard SMPTE 7-color vertical bars.
        case colorBars
        
        /// Background color with a vertical stripe moving horizontally each frame.
        case movingBar(
            baseColor: (b: UInt8, g: UInt8, r: UInt8) = (30, 30, 30),
            barColor: (b: UInt8, g: UInt8, r: UInt8) = (0, 200, 255),
            barWidth: Int = 80
        )
        
        /// Custom procedural generator closure.
        case custom(@Sendable (UInt64, CMTime, CVPixelBuffer) -> Void)
    }
    
    public let frameRate: Double
    public let dimensions: CMVideoDimensions
    
    private var lock = os_unfair_lock()
    private var _isRunning: Bool = false
    private var frameCounter: UInt64 = 0
    private var streamContinuation: AsyncStream<VideoFrame>.Continuation?
    
    private var timer: DispatchSourceTimer?
    private let timerQueue = DispatchQueue(label: "com.fakeme.synthetic.timer", qos: .userInteractive)
    private var pixelBufferPool: CVPixelBufferPool?
    
    public var pattern: Pattern {
        get {
            os_unfair_lock_lock(&lock)
            defer { os_unfair_lock_unlock(&lock) }
            return _pattern
        }
        set {
            os_unfair_lock_lock(&lock)
            defer { os_unfair_lock_unlock(&lock) }
            _pattern = newValue
        }
    }
    private var _pattern: Pattern
    
    private var _onFrame: (@Sendable (VideoFrame) -> Void)?
    public var onFrame: (@Sendable (VideoFrame) -> Void)? {
        get {
            os_unfair_lock_lock(&lock)
            defer { os_unfair_lock_unlock(&lock) }
            return _onFrame
        }
        set {
            os_unfair_lock_lock(&lock)
            defer { os_unfair_lock_unlock(&lock) }
            _onFrame = newValue
        }
    }
    
    public var isRunning: Bool {
        os_unfair_lock_lock(&lock)
        defer { os_unfair_lock_unlock(&lock) }
        return _isRunning
    }
    
    public var frameStream: AsyncStream<VideoFrame> {
        AsyncStream { continuation in
            os_unfair_lock_lock(&lock)
            self.streamContinuation = continuation
            os_unfair_lock_unlock(&lock)
            
            continuation.onTermination = { [weak self] _ in
                guard let self else { return }
                os_unfair_lock_lock(&self.lock)
                self.streamContinuation = nil
                os_unfair_lock_unlock(&self.lock)
            }
        }
    }
    
    public init(
        pattern: Pattern = .colorBars,
        frameRate: Double = 30.0,
        dimensions: CMVideoDimensions = CMVideoDimensions(width: 1280, height: 720)
    ) {
        self._pattern = pattern
        self.frameRate = frameRate
        self.dimensions = dimensions
        self.pixelBufferPool = Self.createPixelBufferPool(
            width: Int(dimensions.width),
            height: Int(dimensions.height)
        )
    }
    
    public convenience init(
        frameRate: Double = 30.0,
        width: Int,
        height: Int
    ) {
        self.init(
            pattern: .colorBars,
            frameRate: frameRate,
            dimensions: CMVideoDimensions(width: Int32(width), height: Int32(height))
        )
    }
    
    deinit {
        timer?.cancel()
        timer = nil
    }
    
    /// Updates the pattern to generate.
    public func setPattern(_ newPattern: Pattern) {
        self.pattern = newPattern
    }
    
    // MARK: - Pool Management
    
    private static func createPixelBufferPool(width: Int, height: Int) -> CVPixelBufferPool? {
        let poolAttributes: [CFString: Any] = [
            kCVPixelBufferPoolMinimumBufferCountKey: 5
        ]
        let pixelBufferAttributes: [CFString: Any] = [
            kCVPixelBufferPixelFormatTypeKey: kCVPixelFormatType_32BGRA,
            kCVPixelBufferWidthKey: width,
            kCVPixelBufferHeightKey: height,
            kCVPixelBufferMetalCompatibilityKey: true,
            kCVPixelBufferIOSurfacePropertiesKey: [:] as [String: Any]
        ]
        var pool: CVPixelBufferPool?
        let status = CVPixelBufferPoolCreate(
            kCFAllocatorDefault,
            poolAttributes as CFDictionary,
            pixelBufferAttributes as CFDictionary,
            &pool
        )
        guard status == kCVReturnSuccess else {
            logger.error("Failed to create CVPixelBufferPool: status \(status)")
            return nil
        }
        return pool
    }
    
    // MARK: - Frame Generation
    
    /// Synchronously generates and advances to the next frame.
    /// Used directly in unit tests for instant deterministic execution without timer waits.
    @discardableResult
    public func generateNextFrame() -> VideoFrame {
        os_unfair_lock_lock(&lock)
        let currentIndex = frameCounter
        frameCounter &+= 1
        let currentPattern = _pattern
        os_unfair_lock_unlock(&lock)
        
        let timescale: CMTimeScale = Int32(frameRate * 1000)
        let frameDurationValue = Int64(1000)
        let presentationTime = CMTime(value: Int64(currentIndex) * frameDurationValue, timescale: timescale)
        
        let width = Int(dimensions.width)
        let height = Int(dimensions.height)
        
        var buffer: CVPixelBuffer?
        if let pool = pixelBufferPool {
            CVPixelBufferPoolCreatePixelBuffer(kCFAllocatorDefault, pool, &buffer)
        }
        if buffer == nil {
            CVPixelBufferCreate(
                kCFAllocatorDefault,
                width,
                height,
                kCVPixelFormatType_32BGRA,
                nil,
                &buffer
            )
        }
        
        guard let pixelBuffer = buffer else {
            fatalError("Could not allocate CVPixelBuffer")
        }
        
        renderPattern(currentPattern, into: pixelBuffer, frameIndex: currentIndex, time: presentationTime)
        
        let frame = VideoFrame(
            pixelBuffer: pixelBuffer,
            timestamp: presentationTime,
            frameIndex: currentIndex
        )
        
        os_unfair_lock_lock(&lock)
        let callback = _onFrame
        let continuation = streamContinuation
        os_unfair_lock_unlock(&lock)
        
        callback?(frame)
        continuation?.yield(frame)
        
        return frame
    }
    
    private func renderPattern(
        _ pattern: Pattern,
        into buffer: CVPixelBuffer,
        frameIndex: UInt64,
        time: CMTime
    ) {
        CVPixelBufferLockBaseAddress(buffer, [])
        defer { CVPixelBufferUnlockBaseAddress(buffer, []) }
        
        guard let baseAddress = CVPixelBufferGetBaseAddress(buffer) else { return }
        let width = CVPixelBufferGetWidth(buffer)
        let height = CVPixelBufferGetHeight(buffer)
        let bytesPerRow = CVPixelBufferGetBytesPerRow(buffer)
        let ptr = baseAddress.assumingMemoryBound(to: UInt8.self)
        
        switch pattern {
        case .solidColor(let b, let g, let r):
            let colorVal = UInt32(b) | (UInt32(g) << 8) | (UInt32(r) << 16) | (0xFF << 24)
            for y in 0..<height {
                let rowPtr = baseAddress.advanced(by: y * bytesPerRow).assumingMemoryBound(to: UInt32.self)
                rowPtr.initialize(repeating: colorVal, count: width)
            }
            
        case .colorBars:
            let barColors: [(b: UInt8, g: UInt8, r: UInt8)] = [
                (255, 255, 255), // White
                (0, 255, 255),   // Yellow
                (255, 255, 0),   // Cyan
                (0, 255, 0),     // Green
                (255, 0, 255),   // Magenta
                (0, 0, 255),     // Red
                (255, 0, 0)      // Blue
            ]
            let barWidth = max(1, width / barColors.count)
            for x in 0..<width {
                let barIdx = min(x / barWidth, barColors.count - 1)
                let col = barColors[barIdx]
                let pixelOffset = x * 4
                ptr[pixelOffset + 0] = col.b
                ptr[pixelOffset + 1] = col.g
                ptr[pixelOffset + 2] = col.r
                ptr[pixelOffset + 3] = 255
            }
            let rowBytes = min(bytesPerRow, width * 4)
            for y in 1..<height {
                memcpy(ptr.advanced(by: y * bytesPerRow), ptr, rowBytes)
            }
            
        case .movingBar(let baseColor, let barColor, let barWidth):
            let speedPixelsPerFrame = 6
            let barPosition = Int((frameIndex * UInt64(speedPixelsPerFrame)) % UInt64(width + barWidth)) - barWidth
            for x in 0..<width {
                let isBar = (x >= barPosition && x < barPosition + barWidth)
                let col = isBar ? barColor : baseColor
                let pixelOffset = x * 4
                ptr[pixelOffset + 0] = col.b
                ptr[pixelOffset + 1] = col.g
                ptr[pixelOffset + 2] = col.r
                ptr[pixelOffset + 3] = 255
            }
            let rowBytes = min(bytesPerRow, width * 4)
            for y in 1..<height {
                memcpy(ptr.advanced(by: y * bytesPerRow), ptr, rowBytes)
            }
            
        case .custom(let generator):
            generator(frameIndex, time, buffer)
        }
    }
    
    // MARK: - VideoFrameProvider Lifecycle
    
    private func tryStart() -> Bool {
        os_unfair_lock_lock(&lock)
        defer { os_unfair_lock_unlock(&lock) }
        guard !_isRunning else { return false }
        _isRunning = true
        return true
    }
    
    private func tryStop() -> Bool {
        os_unfair_lock_lock(&lock)
        defer { os_unfair_lock_unlock(&lock) }
        guard _isRunning else { return false }
        _isRunning = false
        streamContinuation?.finish()
        streamContinuation = nil
        return true
    }
    
    public func start() async throws {
        guard tryStart() else { return }
        
        let intervalMs = Int(1000.0 / frameRate)
        let timer = DispatchSource.makeTimerSource(flags: .strict, queue: timerQueue)
        timer.schedule(
            deadline: .now(),
            repeating: .milliseconds(intervalMs),
            leeway: .milliseconds(1)
        )
        
        timer.setEventHandler { [weak self] in
            guard let self else { return }
            _ = self.generateNextFrame()
        }
        
        self.timer = timer
        timer.resume()
        logger.info("SyntheticFrameProvider started at \(self.frameRate) FPS")
    }
    
    public func stop() async {
        guard tryStop() else { return }
        timer?.cancel()
        timer = nil
        logger.info("SyntheticFrameProvider stopped")
    }
    
    /// Resets frame counter to zero.
    public func resetFrameCounter() {
        os_unfair_lock_lock(&lock)
        frameCounter = 0
        os_unfair_lock_unlock(&lock)
    }
}
